### Code Examples

**Example 1: API Gateway Middleware (ASP.NET Core)**

```csharp
// Custom API Gateway middleware for .NET applications
public class ApiGatewayMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ITenantIdentificationService _tenantService;
    private readonly IRateLimitService _rateLimitService;
    private readonly IAuthenticationService _authService;

    public async Task InvokeAsync(HttpContext context)
    {
        // Step 1: Identify tenant
        var tenantResult = await _tenantService.IdentifyTenantAsync(context.Request);
        if (!tenantResult.Success)
        {
            context.Response.StatusCode = 400;
            await context.Response.WriteAsJsonAsync(new { error = "Invalid tenant" });
            return;
        }

        // Step 2: Authenticate request
        var authResult = await _authService.AuthenticateAsync(context.Request);
        if (!authResult.Success)
        {
            context.Response.StatusCode = 401;
            await context.Response.WriteAsJsonAsync(new { error = "Unauthorized" });
            return;
        }

        // Step 3: Check rate limit
        var rateLimitResult = await _rateLimitService.CheckRateLimitAsync(
            tenantResult.TenantId,
            context.Request.Path);

        if (!rateLimitResult.Allowed)
        {
            context.Response.StatusCode = 429;
            context.Response.Headers.Add("X-RateLimit-Limit",
                rateLimitResult.Limit.ToString());
            context.Response.Headers.Add("X-RateLimit-Remaining", "0");
            context.Response.Headers.Add("Retry-After",
                rateLimitResult.RetryAfterSeconds.ToString());
            await context.Response.WriteAsJsonAsync(new
            {
                error = "Rate limit exceeded",
                retry_after = rateLimitResult.RetryAfterSeconds
            });
            return;
        }

        // Step 4: Inject tenant context for downstream processing
        context.Items["TenantId"] = tenantResult.TenantId;
        context.Items["TenantTier"] = tenantResult.Tier;
        context.Items["UserId"] = authResult.UserId;

        // Step 5: Continue to backend
        await _next(context);

        // Step 6: Add rate limit headers to response
        context.Response.Headers.Add("X-RateLimit-Limit",
            rateLimitResult.Limit.ToString());
        context.Response.Headers.Add("X-RateLimit-Remaining",
            rateLimitResult.Remaining.ToString());
    }
}
```

